package com.thakur.employee.controller; import com.thakur.employee.dto.Requests.*;import com.thakur.employee.model.*;import com.thakur.employee.repository.*;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*; @RestController @RequestMapping("/api/leaves") @RequiredArgsConstructor public class LeaveController {private final LeaveRepository repo;private final UserRepository users;@PostMapping LeaveRequest create(@Valid @RequestBody LeaveCreate r,Authentication a){if(r.endDate().isBefore(r.startDate()))throw new IllegalArgumentException("End date cannot be before start date");return repo.save(LeaveRequest.builder().employee(users.findByEmail(a.getName()).orElseThrow()).startDate(r.startDate()).endDate(r.endDate()).reason(r.reason()).status(RequestStatus.PENDING).createdAt(LocalDateTime.now()).build());}@GetMapping("/mine") List<LeaveRequest> mine(Authentication a){return repo.findByEmployeeEmailOrderByCreatedAtDesc(a.getName());}@GetMapping @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") List<LeaveRequest> all(){return repo.findAllByOrderByCreatedAtDesc();}@PatchMapping("/{id}/decision") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") LeaveRequest decide(@PathVariable Long id,@RequestBody Decision d){var x=repo.findById(id).orElseThrow();x.setStatus(RequestStatus.valueOf(d.status().toUpperCase()));x.setManagerComment(d.comment());return repo.save(x);}}
